from math import sqrt

def paired_t(x, y):
    """Paired t statistic for mean(x - y). Raise ValueError if the lengths differ."""
    if len(x) != len(y):
        raise ValueError("x and y must pair up")
    d = [a - b for a, b in zip(x, y)]
    n = len(d)
    m = sum(d) / n
    s = sqrt(sum((v - m) ** 2 for v in d) / (n - 1))
    return m / (s / sqrt(n))
